func (q *Queries) SetAccrued(ctx context.Context, arg SetAccruedParams) error {
	_, err := q.db.Exec(ctx, setAccrued, arg.UserIds, arg.Accrued, arg.Live)
	return err
}

const setStoppedSince = `-- name: SetStoppedSince :exec
insert into metering_state (singleton, stopped_since) values (true, $1)
on conflict (singleton) do update set stopped_since = excluded.stopped_since
`

func (q *Queries) SetStoppedSince(ctx context.Context, stoppedSince time.Time) error {
	_, err := q.db.Exec(ctx, setStoppedSince, stoppedSince)
	return err
}

const stoppedMeteredContainers = `-- name: StoppedMeteredContainers :many
select c.id, c.workspace_id, c.release_id, c.image_build_id, c.cpu_millis, c.memory_bytes,
       c.gpu_count, c.gpu_type, c.rate_class, c.billing_owner,
       c.ready_at::timestamptz as ready_at, c.stopped_at, c.stop_reason, h.last_seen_at,
       w.id as workload_id, w.app_id, o.user_id as owner_id, u.billed_through,
       coalesce(u.complete, false)::bool as complete
from containers c
join workspace_members o on o.workspace_id = c.workspace_id and o.role = 'owner'
left join hosts h on h.id = c.host_id
left join releases r on r.id = c.release_id
left join workloads w on w.id = r.workload_id
left join usage_cursors u on u.source_kind = 'container' and u.source_id = c.id
where c.ready_at is not null and c.stopped_at >= $1 and not coalesce(u.complete, false)
`

type StoppedMeteredContainersRow struct {
	ID            uuid.UUID
	WorkspaceID   uuid.UUID
	ReleaseID     *uuid.UUID
	ImageBuildID  *uuid.UUID
	CpuMillis     int64
	MemoryBytes   int64
	GpuCount      int32
	GpuType       string
	RateClass     string
	BillingOwner  string
	ReadyAt       time.Time
	StoppedAt     *time.Time
	StopReason    *string
	LastSeenAt    *time.Time
	WorkloadID    *uuid.UUID
	AppID         *uuid.UUID
	OwnerID       uuid.UUID
	BilledThrough *time.Time
	Complete      bool
}

// Containers that stopped since the look-back began and still owe their
// last entries.
func (q *Queries) StoppedMeteredContainers(ctx context.Context, since *time.Time) ([]StoppedMeteredContainersRow, error) {
	rows, err := q.db.Query(ctx, stoppedMeteredContainers, since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []StoppedMeteredContainersRow
	for rows.Next() {
		var i StoppedMeteredContainersRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.ReleaseID,
			&i.ImageBuildID,
			&i.CpuMillis,
			&i.MemoryBytes,
			&i.GpuCount,
			&i.GpuType,
			&i.RateClass,
			&i.BillingOwner,
			&i.ReadyAt,
			&i.StoppedAt,
			&i.StopReason,
			&i.LastSeenAt,
			&i.WorkloadID,
			&i.AppID,
			&i.OwnerID,
			&i.BilledThrough,
			&i.Complete,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const tryMeteringLock = `-- name: TryMeteringLock :one
select pg_try_advisory_lock(hashtextextended('billing-metering', 0))::bool
`

// Held for the metering pass by its session, so replicas skip a pass
// another is running.
func (q *Queries) TryMeteringLock(ctx context.Context) (bool, error) {
	row := q.db.QueryRow(ctx, tryMeteringLock)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}
